use pcb_analyze::extraction::local::{mesh::{self,LayeredMesh,Tetrahedron,CopperTetrahedron,InterfaceFace},field_refinement::{self,Saved},volume_current,volume_field::{Field,DenseField,ElectricApply},AllocationBudget};
use std::{collections::BTreeMap,time::Duration};
fn budget()->AllocationBudget{AllocationBudget{max_bytes:32*1024*1024,max_nodes:1000,max_tetrahedra:1000}}
fn seed()->LayeredMesh{
 let nodes_m=vec![[0.,0.,0.],[0.001,0.,0.],[0.,0.001,0.],[0.,0.,0.001],[0.,0.,-0.001]];let f=[0,1,2,3];let c=[0,2,1,4];let(v,g)=mesh::tetra_coefficients(f.map(|i|nodes_m[i])).unwrap();let(cv,cg)=mesh::tetra_coefficients(c.map(|i|nodes_m[i])).unwrap();
 LayeredMesh{nodes_m,tetrahedra:vec![Tetrahedron{nodes:f,slab:0,planar_triangle:0,epsilon_r:4.2,material_label:"test-dielectric".into(),volume_m3:v,gradients_per_m:g}],copper_tetrahedra:vec![CopperTetrahedron{nodes:c,slab:0,planar_triangle:0,source_ids:vec!["physical-copper".into()],volume_m3:cv,gradients_per_m:cg}],copper_interfaces:vec![InterfaceFace{nodes:[0,1,2],copper_source_ids:vec!["physical-copper".into()]}],external_faces:vec![[0,1,3],[0,2,3],[1,2,3]],dielectric_volume_m3:v,copper_volume_m3:cv,planned_peak_bytes:0}
}
fn saved(mesh:&LayeredMesh,space:&volume_current::Space)->Saved{
 let mut nodes=mesh.nodes_m.clone();nodes.push([0.0005,0.,0.]);let mut weights=BTreeMap::new();for node in[0,1,2,4]{weights.insert(node.to_string(),vec![(space.node_potential[&node],1.)]);}let mut midpoint=BTreeMap::new();for node in[0,1]{*midpoint.entry(space.node_potential[&node]).or_insert(0.)+=0.5;}weights.insert("5".into(),midpoint.into_iter().collect());
 Saved{nodes_m:nodes,node_bits:None,copper_cells:vec![[0,2,1,4]],field_cells:vec![[5,1,2,3],[0,5,2,3]],field_epsilon_r:vec![4.2,4.2],field_epsilon_bits:None,external_faces:vec![[0,5,3],[5,1,3],[0,2,3],[1,2,3]],field_metal_faces:vec![[0,5,2],[5,1,2]],field_metal_nodes:vec![0,1,2,4,5],field_trace_weights:weights,field_trace_weight_bits:None,field_initial_node_count:5,field_node_parent_edges:vec![[0,1]],field_node_parent_fractions:vec![],field_coordinate_model:None}
}
#[test]
fn native_edge_star_preserves_affine_trace_contact_area_and_exact_element_energy(){
 for(contact,fraction,exact)in[false,true].into_iter().flat_map(|c|[0.25,0.5,0.75].into_iter().flat_map(move|f|[false,true].map(move|e|(c,f,e)))){let mesh=seed();let electrodes=if contact{vec![vec![0,1,2]]}else{vec![]};let space=volume_current::assemble(&mesh,&[58e6],&electrodes,budget()).unwrap();let mut target=saved(&mesh,&space);target.field_node_parent_fractions=vec![fraction];if exact{target.field_coordinate_model=Some("exact-dyadic-edge-ancestry-v1".into());}target.nodes_m[5]=[0.001*fraction,0.,0.];let mut weights=BTreeMap::new();for(node,weight)in[(0,1.-fraction),(1,fraction)]{*weights.entry(space.node_potential[&node]).or_insert(0.)+=weight;}target.field_trace_weights.insert("5".into(),weights.into_iter().collect());let mut refined=field_refinement::replay(mesh.clone(),&mesh,&space,&target,budget(),Duration::from_secs(5)).unwrap();assert_eq!(refined.mesh.copper_tetrahedra[0].nodes,mesh.copper_tetrahedra[0].nodes);assert_eq!(refined.mesh.copper_volume_m3.to_bits(),mesh.copper_volume_m3.to_bits());assert_eq!(refined.mesh.tetrahedra.len(),2);assert!(refined.maximum_parent_volume_error<1e-14);
  let phi=|p:[f64;3]|1.+if contact{-1000.*p[2]}else{2.*p[0]-3.*p[1]-1000.*p[2]};let u=space.mesh_nodes.iter().map(|ns|phi(mesh.nodes_m[ns[0]])).collect::<Vec<_>>();for row in &refined.metal_trace{let value=row.weights.iter().map(|&(i,w)|w*u[i]).sum::<f64>();assert!((value-phi(refined.mesh.nodes_m[row.node])).abs()<1e-14);}
  let trace=std::mem::take(&mut refined.metal_trace);let field=Field::new_conforming_trace(&refined.mesh,space.potential_count(),trace,budget()).unwrap();let dense=DenseField::new(&field,budget()).unwrap();let charge=dense.apply(&u).unwrap();let actual=u.iter().zip(&charge).map(|(v,q)|v*q).sum::<f64>();let expected=8.8541878128e-12*4.2*mesh.dielectric_volume_m3*(1e6+if contact{0.}else{13.});assert!((actual-expected).abs()/expected<1e-10);
  let mut buried=vec![0.;space.potential_count()];buried[space.node_potential[&4]]=1.;assert!(dense.apply(&buried).unwrap().iter().all(|&v|v==0.));assert_eq!(refined.original_potential_count,space.potential_count());
 }
}
#[test]
fn native_replay_refuses_wrong_geometry_ancestry_trace_material_and_budget(){
 let mesh=seed();let space=volume_current::assemble(&mesh,&[58e6],&[],budget()).unwrap();let original=saved(&mesh,&space);
 let mut wrong=original.clone();wrong.nodes_m[5][0]+=1e-8;assert!(field_refinement::replay(mesh.clone(),&mesh,&space,&wrong,budget(),Duration::from_secs(5)).err().unwrap().contains("node bits"));
 let mut wrong=original.clone();wrong.field_node_parent_edges[0]=[0,4];assert!(field_refinement::replay(mesh.clone(),&mesh,&space,&wrong,budget(),Duration::from_secs(5)).err().unwrap().contains("actual native field"));
 let mut wrong=original.clone();wrong.field_epsilon_r[0]=1.1;assert!(field_refinement::replay(mesh.clone(),&mesh,&space,&wrong,budget(),Duration::from_secs(5)).err().unwrap().contains("material"));
 let mut wrong=original.clone();wrong.field_trace_weights.insert("5".into(),vec![(space.node_potential[&0],0.25),(space.node_potential[&1],0.75)]);assert!(field_refinement::replay(mesh.clone(),&mesh,&space,&wrong,budget(),Duration::from_secs(5)).err().unwrap().contains("trace differs"));
 let mut changed=mesh.clone();changed.copper_tetrahedra[0].source_ids.push("fabricated-source".into());assert!(field_refinement::replay(changed,&mesh,&space,&original,budget(),Duration::from_secs(5)).err().unwrap().contains("source ownership"));
 assert!(field_refinement::replay(mesh.clone(),&mesh,&space,&original,AllocationBudget{max_bytes:1,..budget()},Duration::from_secs(5)).err().unwrap().contains("MEMORY_LIMIT"));
 assert!(field_refinement::replay(mesh.clone(),&mesh,&space,&original,AllocationBudget{max_tetrahedra:2,..budget()},Duration::from_secs(5)).is_err());
 let mut wrong=original.clone();wrong.copper_cells[0][0]=usize::MAX;assert!(field_refinement::replay(mesh.clone(),&mesh,&space,&wrong,budget(),Duration::from_secs(5)).is_err());
 assert!(field_refinement::replay(mesh.clone(),&mesh,&space,&original,budget(),Duration::ZERO).err().unwrap().contains("DEADLINE"));
}

#[test]
fn exact_dyadic_actual_thin_parent_matches_frozen_fraction_coefficients(){
 let data:serde_json::Value=serde_json::from_str(include_str!("../../../tests/fixtures/analysis-local-extraction/board-integration/exact-dyadic-field-reference.json")).unwrap();
 let decode=|v:&serde_json::Value|->Vec<[f64;3]>{v.as_array().unwrap().iter().map(|p|std::array::from_fn(|k|f64::from_bits(p[k].as_u64().unwrap()))).collect()};
 let all=decode(&data["allNodeBits"]);let nodes=all[..8].to_vec();let(fv,fg)=mesh::tetra_coefficients([0,1,2,3].map(|i|nodes[i])).unwrap();let(cv,cg)=mesh::tetra_coefficients([4,5,6,7].map(|i|nodes[i])).unwrap();
 let initial=LayeredMesh{nodes_m:nodes,tetrahedra:vec![Tetrahedron{nodes:[0,1,2,3],slab:0,planar_triangle:0,epsilon_r:1.,material_label:"actual-air-parent".into(),volume_m3:fv,gradients_per_m:fg}],copper_tetrahedra:vec![CopperTetrahedron{nodes:[4,5,6,7],slab:0,planar_triangle:0,source_ids:vec!["control-copper".into()],volume_m3:cv,gradients_per_m:cg}],copper_interfaces:vec![],external_faces:vec![[0,1,2],[0,1,3],[0,2,3],[1,2,3]],dielectric_volume_m3:fv,copper_volume_m3:cv,planned_peak_bytes:0};
 let space=volume_current::assemble(&initial,&[58e6],&[],budget()).unwrap();let rows=data["cells"].as_array().unwrap();let mut weights=BTreeMap::new();for node in[4,5,6,7]{weights.insert(node.to_string(),vec![(space.node_potential[&node],1.)]);}
 let saved=Saved{nodes_m:all,node_bits:None,copper_cells:vec![[4,5,6,7]],field_cells:serde_json::from_value(serde_json::Value::Array(rows.iter().map(|r|r["nodes"].clone()).collect())).unwrap(),field_epsilon_r:vec![1.;rows.len()],field_epsilon_bits:None,external_faces:serde_json::from_value(data["externalFaces"].clone()).unwrap(),field_metal_faces:vec![],field_metal_nodes:vec![4,5,6,7],field_trace_weights:weights,field_trace_weight_bits:None,field_initial_node_count:8,field_node_parent_edges:serde_json::from_value(data["parentEdges"].clone()).unwrap(),field_node_parent_fractions:vec![],field_coordinate_model:Some("exact-dyadic-edge-ancestry-v1".into())};
 let replay=field_refinement::replay(initial.clone(),&initial,&space,&saved,budget(),Duration::from_secs(5)).unwrap();assert!(replay.maximum_parent_volume_error<1e-20);
 for cell in &replay.mesh.tetrahedra{let expected=rows.iter().find(|r|serde_json::from_value::<[usize;4]>(r["nodes"].clone()).unwrap()==cell.nodes).unwrap();let volume=expected["volumeM3"].as_f64().unwrap();assert!((cell.volume_m3-volume).abs()/volume<1e-13);for i in 0..4{for k in 0..3{let g=expected["gradientsPerM"][i][k].as_f64().unwrap();assert!((cell.gradients_per_m[i][k]-g).abs()/g.abs().max(1.)<1e-13);}}}
 let mut rounded=saved.clone();rounded.field_coordinate_model=None;assert!(field_refinement::replay(initial.clone(),&initial,&space,&rounded,budget(),Duration::from_secs(5)).err().unwrap().contains("partition"));
 let mut bad=saved;bad.field_coordinate_model=Some("unknown-coordinate-model".into());assert!(field_refinement::replay(initial.clone(),&initial,&space,&bad,budget(),Duration::from_secs(5)).err().unwrap().contains("coordinate model"));
}
